test("promotion accepts canonical records produced by the activation service journal", async () => {
  const f = fixture();
  const { journal, states } = activationJournal();
  let current: ApplicationActiveRecord | null = null;
  const activationService = new ApplicationActivationService({
    mutations: journal,
    readActive: async () => structuredClone(current),
    writeActive: async record => { current = structuredClone(record); },
    confirmActive: async () => {}, checkCompatibility: async () => {}, prepare: async () => {},
    stop: async () => {}, start: async () => {}, requireReady: async () => {}, requireStopped: async () => {},
    route: async () => {}, verifyRoute: async () => {},
  });
  await activationService.activate({
    runtime: f.source.runtime, environment: { api: { DATABASE_URL: "synthetic-local-fixture" } },
    hosts: f.source.hosts, configurationId, expectedActivationId: null,
    principal: { type: "master", id: "fixture" },
  });
  expect(current).not.toBeNull();
  Object.assign(f.source, current);
  Object.assign(f.sourceState, states.get(activation)!);
  expect(f.sourceState.resourceKey).toStartWith("v1/application_release/");
  const plan = await f.service.readPlan(f.input);
  expect(plan.source.receipt_confirmed).toBe(true);
  expect(plan.action).toBe("promote");
  expect(JSON.stringify(plan)).not.toContain("synthetic-local-fixture");
});

test("an unqualified resource digest cannot authorize a promotion", async () => {
  const f = fixture();
  f.sourceState.resourceKey = stableSha256({ applicationId: "reviews", environmentId: "staging" });
  expect((await f.service.readPlan(f.input)).blockers).toContain("SOURCE_RECEIPT_UNCONFIRMED");
});

test.each(["fingerprint", "checkpoint", "phase", "configuration", "desired"] as const)(
  "a success-shaped receipt cannot hide invalid %s journal evidence", async fault => {
    const f = fixture();
    if (fault === "fingerprint") f.sourceState.requestFingerprint = "d".repeat(64);
    if (fault === "checkpoint") f.sourceState.checkpoint = {};
    if (fault === "phase") f.sourceState.checkpoint["phase"] = "healthy";
    if (fault === "configuration" || fault === "desired") {
      const desired = f.sourceState.checkpoint["desired"] as Record<string, unknown>;
      if (fault === "configuration") desired["configurationId"] = activation;
      else desired["configurationDigest"] = "d".repeat(64);
    }
    const plan = await f.service.readPlan(f.input);
    expect(plan.action).toBe("blocked");
    expect(plan.blockers).toContain("SOURCE_RECEIPT_UNCONFIRMED");
  },
);

